const TypeGLTFMesh: FC<{ 
  url: string; 
  onPointerDown: any; 
  onPointerUp: any; 
  onPointerMove: any; 
  onPointerOut: any 
}> = ({ url, onPointerDown, onPointerUp, onPointerMove, onPointerOut }) => {
  const gltf = useGLTF(url);
  const plasterColor = useMemo(() => new THREE.Color(getComputedColorForMesh("--plaster")), []);
  const plasterEdgeColor = useMemo(() => new THREE.Color(getComputedColorForMesh("--plaster-edge")), []);

  const clonedScene = useMemo(() => {
    const cloned = gltf.scene.clone();
    const plasterMaterial = new THREE.MeshStandardMaterial({
      color: plasterColor,
      flatShading: false,
      metalness: 0,
      roughness: 0.8,
    });
    const edgeMaterial = new THREE.LineBasicMaterial({ color: plasterEdgeColor });
    cloned.traverse((child) => {
      if (child instanceof THREE.Mesh) {
        child.raycast = THREE.Mesh.prototype.raycast;
        if (Array.isArray(child.material)) {
          child.material = child.material.map(() => plasterMaterial.clone());
        } else {
          child.material = plasterMaterial.clone();
        }
      }
    });
    return cloned;
  }, [gltf.scene, plasterColor, plasterEdgeColor]);

  return <primitive object={clonedScene} onPointerDown={onPointerDown} onPointerUp={onPointerUp} 
                      onPointerMove={onPointerMove} onPointerOut={onPointerOut} />;
};
```

