const ModelPiece: FC<ModelPieceProps> = () => {
  const piece = usePiece() as Piece;
  const isSelected = useIsPieceSelected();
  const isHovered = useIsPieceTransitiveHovered();  // ← Pulls from HoverPiecesContext
  const [selection, setSelection] = useDesignAppSelection();
  const [hoverPiece] = useDesignAppHoverPiece();    // ← Action to set hover
  const [clearHover] = useDesignAppClearHover();    // ← Action to clear hover
  const [focusPiece] = useDesignAppFocusPiece();
  const { currentHoveredPieceGuidRef } = useHoverIntent();

  // Compute highlight color based on hover/selected state
  const highlightColor = useMemo(() => 
    (isSelected ? activeBaseColor : isHovered ? hoverBaseColor : null), 
    [isSelected, isHovered, activeBaseColor, hoverBaseColor]
  );

  // Pointer event handlers
  const handlePointerEnter = useCallback(
    (e?: ThreeEvent<PointerEvent>) => {
      e?.stopPropagation();
      if (currentHoveredPieceGuidRef.current !== piece.guid) {
        currentHoveredPieceGuidRef.current = piece.guid;
        if (hoverPiece) hoverPiece(piece.guid);  // ← TRIGGER: dispatch hover action
      }
    },
    [piece.guid, hoverPiece, currentHoveredPieceGuidRef],
  );

  const handlePointerLeave = useCallback(
    (e?: ThreeEvent<PointerEvent>) => {
      e?.stopPropagation();
      if (currentHoveredPieceGuidRef.current === piece.guid) {
        currentHoveredPieceGuidRef.current = null;
        if (clearHover) clearHover();  // ← TRIGGER: clear hover action
      }
    },
    [piece.guid, clearHover, currentHoveredPieceGuidRef],
  );

  return (
    <>
      {originalMeshContent}
      {pieceMatrix && (
        <group userData={userData} matrix={pieceMatrix} matrixAutoUpdate={false}>
          {diffedMeshContent}
          {/* Geometry or PieceMesh receives handlers */}
          <Geometry
            selected={isSelected}
            hovered={isHovered}           // ← Passed to component
            onClick={onSelect}
            onDoubleClick={onDoubleClick}
            onPointerEnter={handlePointerEnter}  // ← Handler attached
            onPointerLeave={handlePointerLeave}  // ← Handler attached
            color={materialColor}
            emissiveColor={emissiveColor}
            emissiveIntensity={0.45}
            showEdges
            userData={userData}
          />
        </group>
      )}
    </>
  );
};
