### 7. **Material/Color Update Logic - Geometry Component**

[/workspaces/semio/elements/ui/index.tsx](https://vscode-file-links/workspaces/semio/elements/ui/index.tsx#L18001)

```typescript
export const Geometry: React.FC<GeometryProps> = ({ 
  children, 
  selected = false, 
  hovered = false,  // ← Receives hover state prop
  onClick, 
  onDoubleClick, 
  onPointerEnter, 
  onPointerLeave, 
  color, 
  emissiveColor, 
  emissiveIntensity = 0.45, 
  showEdges = true, 
  edgeColor, 
  userData 
}) => {
  const foregroundColor = React.useMemo(() => getComputedColor("--foreground"), []);
  const activeBaseColor = React.useMemo(() => getComputedColor("--active-base"), []);
  const hoverBaseColor = React.useMemo(() => getComputedColor("--hover-base"), []);

  // CONDITIONAL COLOR SELECTION based on hover/selected
  const resolvedColor = React.useMemo(() => {
    if (selected) return activeBaseColor;      // Selected takes priority
    if (hovered) return hoverBaseColor;        // Then hover
    if (color) return color;                   // Then provided color
    return foregroundColor;                    // Default
  }, [color, selected, hovered, activeBaseColor, hoverBaseColor, foregroundColor]);

  // EMISSIVE color follows same logic
  const resolvedEmissiveColor = React.useMemo(() => {
    if (selected) return activeBaseColor;
    if (hovered) return hoverBaseColor;
    if (emissiveColor) return emissiveColor;
    return resolvedColor;
  }, [selected, hovered, activeBaseColor, hoverBaseColor, emissiveColor, resolvedColor]);

  // EDGE color follows same logic
  const resolvedEdgeColor = React.useMemo(() => {
    if (edgeColor) return edgeColor;
    if (selected) return activeBaseColor;
    if (hovered) return hoverBaseColor;
    return foregroundColor;
  }, [edgeColor, selected, hovered, activeBaseColor, hoverBaseColor, foregroundColor]);

  return (
    <group userData={userData} onClick={onClick} onDoubleClick={onDoubleClick} 
           onPointerEnter={handlePointerEnter} onPointerLeave={handlePointerLeave}>
      {children ? (
        children
      ) : (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshStandardMaterial 
            color={resolvedColor} 
            emissive={resolvedEmissiveColor} 
            emissiveIntensity={emissiveIntensity} 
          />
          {showEdges && <Edges scale={1.001} color={resolvedEdgeColor} />}
        </mesh>
      )}
    </group>
  );
};
```

