### 9. **PieceMesh Component - Type Model Selection**

[Line 37778-37875](https://vscode-file-links/workspaces/semio/compose/sketchpad/index.tsx#L37778-L37875)

Model selection logic with file blob URL loading:
```typescript
const PieceMesh: FC<{ highlightColor: string | null } & DesignMeshEventProps> = ({ 
  highlightColor, 
  onClick, 
  onDoubleClick, 
  onPointerEnter, 
  onPointerLeave 
}) => {
  const piece = usePiece() as Piece;
  const type = useType(undefined, typeof piece.type === "string" ? piece.type : piece.type?.guid) as Type | undefined;
  const typeConcepts = type?.concepts;
  const files = useKitFiles();
  const kitStore = useKitStore() as CollaborativeKitStore;
  const [selectedModelTags] = useDesignAppSelectedModelTags();

  const { modelUrl, fileExtension, fileGuid, modelGuid } = useMemo(() => {
    // 1. Get models from type
    if (!type?.models || type.models.length === 0) {
      return { modelUrl: null, fileExtension: "", fileGuid: null, modelGuid: null };
    }

    // 2. Select best model (by tags > type concepts > default)
    let model: Model | undefined;
    const tagsForType = selectedModelTags[type.guid] ?? [];
    if (tagsForType.length > 0) {
      model = selectBestModel(type.models, tagsForType);
    } else {
      const conceptGuids = typeConcepts?.map((c) => c.guid) ?? [];
      model = findModel(type.models, conceptGuids);
    }

    // 3. Get file from kit store
    const fileId = typeof model.file === "string" ? model.file : model.file?.guid;
    const file = files.find((f) => f.guid === fileId);

    // 4. Get blob URL for file
    const ext = file.name?.split(".").pop() || "";
    const url = kitStore.getFileUrl(file.guid);

    return { modelUrl: url, fileExtension: ext, fileGuid: file.guid, modelGuid: model.guid };
  }, [type, typeConcepts, files, kitStore, selectedModelTags]);

  return (
    <Suspense fallback={null}>
      <LoadedPieceMesh 
        url={blobUrl} 
        fileExtension={fileExtension} 
        highlightColor={highlightColor} 
        onClick={onClick} 
        onDoubleClick={onDoubleClick} 
        onPointerEnter={onPointerEnter} 
        onPointerLeave={onPointerLeave} 
      />
    </Suspense>
  );
};
```

