const EMPTY_HOVER_CONTEXT: HoverPiecesContextValue = {
  transitivelyHoveredPieces: new Set(),
  transitivelyHoveredTypes: new Set(),
};

/**
 * HoverPiecesStore is a lightweight pub/sub store that holds computed hover data
 * and notifies subscribers when the data changes. Consumers use useSyncExternalStore
 * with per-piece/type selectors to avoid O(N) re-renders from React Context fan-out.
 * [👤compose📚js🗃️sketchpad💻design🔖imports🔖store🪨hoverpiecesstore](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Store/d/i/HoverPiecesStore)
 **/
class HoverPiecesStore {
  private _data: HoverPiecesContextValue = EMPTY_HOVER_CONTEXT;
  private _listeners = new Set<() => void>();
  get data(): HoverPiecesContextValue { return this._data; }
  update(newData: HoverPiecesContextValue): void {
    if (areHoverContextsEqual(this._data, newData)) return;
    this._data = newData;
    for (const listener of this._listeners) listener();
  }
  subscribe = (listener: () => void): (() => void) => {
    this._listeners.add(listener);
    return () => { this._listeners.delete(listener); };
